USE CATALOG dcp_synth;
CREATE OR REPLACE VIEW `03_gold`.dp16_regulatory_product_master AS SELECT product_id,product_name,product_class,lead_market,lifecycle_status,source_id,CAST(updated_at AS TIMESTAMP) updated_at,_run_id FROM `06_regulatory`.product_master;
CREATE OR REPLACE VIEW `03_gold`.dp19_regulatory_submission_master AS SELECT submission_id,submission_type,product_id,market,authority,workflow_stage,CAST(planned_submission_date AS DATE) planned_submission_date,CAST(actual_submission_date AS DATE) actual_submission_date,CAST(authority_due_date AS DATE) authority_due_date,owner,risk_status,source_id,CAST(updated_at AS TIMESTAMP) updated_at,_run_id FROM `06_regulatory`.submission_master;
CREATE OR REPLACE VIEW `03_gold`.dp21_regulatory_authority_interactions AS SELECT i.interaction_id,i.submission_id,s.product_id,s.market,s.authority,i.interaction_type,CAST(i.received_date AS DATE) received_date,CAST(i.response_due_date AS DATE) response_due_date,i.status,i.source_id,CAST(i.ingested_at AS TIMESTAMP) ingested_at,i._run_id FROM `06_regulatory`.authority_interactions i LEFT JOIN `06_regulatory`.submission_master s ON i.submission_id=s.submission_id;
